# -*- coding: utf-8 -*-
"""§8.2 분절 규칙 — 실패 유형 4종 주입 검증 (신규 파일).

29차에서는 "랜드마크 1점 이동"만 주입했다. 여기서는 **실제로 발생하는 실패 유형**을 주입하고,
규칙이 그 유형을 **검출하는지**, 그리고 **정상 프레임을 오검출하지 않는지**를 함께 잰다.

주입 유형 (0.5초 = 약 8프레임, 손당 시행마다 1회)
    I1 배경 도약   : Landmark 8(검지끝)을 150 mm 이동 — 추적이 배경으로 튐
    I2 완전 소실   : Landmark 8 을 결측(nan) — 손끝 가림/검출 실패
    I3 스케일 오류 : 전 랜드마크를 손목 기준 1.5배 확대 — 깊이/스케일 오추정
    I4 물체 가림   : Landmark 8 을 손목 위치로 붕괴 — 손끝이 손목으로 접힘

비교 규칙 (모두 `|L−L̂|/L̂ > 0.20` 임계, **프레임당 2개 이상 분절 위반 = 불일치**)
    현행  : L̂ = 비장애 개발군에서 계산한 분절별 **고정 기준 길이**(중앙값)
    B안   : L̂(θ) = a0 + a1θ + a2θ²  (θ = 그 분절이 속한 손가락 굴곡각 합, deg)

주의(정직)
    · B안 계수를 **비장애 세션 1개에서 적합하고 같은 세션에서 평가**한다 → 순환. 오검출률이 낙관적이다.
      실제 사양은 "개발군(비환자 6명)"에서 적합·동결해야 하며 그 자료는 아직 없다.
    · 주입은 3D 랜드마크에만 가한다. 깊이·픽셀 열은 건드리지 않는다.
    · 환자 세션에는 영상 정답이 없으므로, 여기서 재는 것은 **합성 주입 검출률**뿐이다.

출력: experiments/results/v15_failure_injection.json
"""
from __future__ import annotations
import csv, glob, io, json, math, os
import numpy as np

ROOT = "capstone/호진파일/outputs/데이터_저장"
OUT = "experiments/results/v15_failure_injection.json"

SEG_FINGER = {
    (1, 2): "Thumb", (2, 3): "Thumb", (3, 4): "Thumb",
    (5, 6): "Index", (6, 7): "Index", (7, 8): "Index",
    (9, 10): "Middle", (10, 11): "Middle", (11, 12): "Middle",
    (13, 14): "Ring", (13, 14): "Ring", (14, 15): "Ring", (15, 16): "Ring",
    (17, 18): "Pinky", (18, 19): "Pinky", (19, 20): "Pinky",
}
SEGMENTS = [(1, 2), (2, 3), (3, 4), (5, 6), (6, 7), (7, 8),
            (9, 10), (10, 11), (11, 12), (13, 14), (14, 15), (15, 16),
            (17, 18), (18, 19), (19, 20)]
FINGER_JOINTS = {"Thumb": [(0, 1, 2), (1, 2, 3)], "Index": [(5, 6, 7)], "Middle": [(9, 10, 11)],
                 "Ring": [(13, 14, 15)], "Pinky": [(17, 18, 19)]}
THRESH, MIN_SEG = 0.20, 2


def rd(p):
    with io.open(p, encoding="utf-8-sig") as fh:
        return list(csv.DictReader(fh))


def fl(x):
    try:
        v = float(x)
        return v if math.isfinite(v) else None
    except (TypeError, ValueError):
        return None


def interior(a, b, c):
    v1, v2 = a - b, c - b
    n1, n2 = np.linalg.norm(v1), np.linalg.norm(v2)
    if n1 < 1e-9 or n2 < 1e-9:
        return np.nan
    return math.degrees(math.acos(max(-1.0, min(1.0, float(np.dot(v1, v2) / (n1 * n2))))))


def load_windows(sd, hand):
    """(프레임배열 P, 원본 프레임 인덱스) 목록. 시간축=capture_monotonic_s."""
    out = []
    for lf in sorted(glob.glob(os.path.join(sd, "split", "*", "Trial_*", "*_landmarks.csv"))):
        if "pose_landmarks" in lf:
            continue
        df = lf.replace("_landmarks.csv", "_distance_comparison.csv")
        mono = {}
        if os.path.exists(df):
            for r in rd(df):
                if (r.get("Hand") or "") != hand:
                    continue
                fid, t = fl(r.get("Frame_ID")), fl(r.get("capture_monotonic_s"))
                if fid is not None and t is not None:
                    mono[int(fid)] = t
        by = {}
        with io.open(lf, encoding="utf-8-sig") as fh:
            for r in csv.DictReader(fh):
                if (r.get("Hand") or "").strip() != hand:
                    continue
                try:
                    fid = int(float(r["Frame_ID"])); lid = int(float(r["Landmark_ID"]))
                except (KeyError, TypeError, ValueError):
                    continue
                xyz = (fl(r.get("MP_X_m")), fl(r.get("MP_Y_m")), fl(r.get("MP_Z_m")))
                if all(v is not None for v in xyz):
                    by.setdefault(fid, {})[lid] = xyz
        if len(by) < 20:
            continue
        fids = [k for k in sorted(by) if all(0 <= l < 21 for l in by[k])]
        P = np.full((len(fids), 21, 3), np.nan)
        t = np.full(len(fids), np.nan)
        for i, fid in enumerate(fids):
            for lid, xyz in by[fid].items():
                if 0 <= lid <= 20:
                    P[i, lid] = xyz
            tv = mono.get(fid)
            if tv is not None:
                t[i] = tv
        good = np.isfinite(P[:, 0]).all(axis=1)
        P = P[good]
        if P.shape[0] < 20:
            continue
        out.append({"trial": os.path.basename(os.path.dirname(lf)), "P": P})
    return out


def seg_lengths(P):
    n = P.shape[0]
    L = np.full((n, len(SEGMENTS)), np.nan)
    for j, (a, b) in enumerate(SEGMENTS):
        L[:, j] = np.linalg.norm(P[:, a] - P[:, b], axis=-1)
    return L


def finger_theta(P):
    """손가락별 굴곡각 합 (deg), (n,5)."""
    flx = np.full((P.shape[0], 5), np.nan)
    for k, fg in enumerate(("Thumb", "Index", "Middle", "Ring", "Pinky")):
        acc = np.zeros(P.shape[0])
        cnt = np.zeros(P.shape[0])
        for (i1, i2, i3) in FINGER_JOINTS[fg]:
            for fr in range(P.shape[0]):
                v = 180.0 - interior(P[fr, i1], P[fr, i2], P[fr, i3])
                if np.isfinite(v):
                    acc[fr] += v
                    cnt[fr] += 1
        flx[:, k] = np.where(cnt > 0, acc / np.maximum(cnt, 1) * cnt, np.nan)
    return flx


def violations(L, Lhat):
    """프레임별 위반 분절 수. Lhat 은 (15,) 또는 (n,15)."""
    with np.errstate(invalid="ignore", divide="ignore"):
        rel = np.abs(L - Lhat) / np.where(np.abs(Lhat) < 1e-9, np.nan, np.abs(Lhat))
    return np.sum(rel > THRESH, axis=1)


def inject(P, kind, idx0, width, rng):
    Q = P.copy()
    sl = slice(idx0, min(idx0 + width, P.shape[0]))
    if kind == "I1_jump":
        d = rng.normal(size=3)
        d = d / np.linalg.norm(d) * 0.150
        Q[sl, 8] = Q[sl, 8] + d
    elif kind == "I2_loss":
        Q[sl, 8] = np.nan
    elif kind == "I3_scale":
        w = P[sl, 0:1, :]
        Q[sl] = w + 1.5 * (P[sl] - w)
    elif kind == "I4_collapse":
        Q[sl, 8] = P[sl, 0]
    return Q, sl


def main():
    sessions = [d for d in sorted(os.listdir(ROOT)) if os.path.isdir(os.path.join(ROOT, d))]
    rng = np.random.default_rng(20261002)

    # --- 비장애 개발군에서만 적합 ---
    healthy = None
    for d in sessions:
        m = glob.glob(os.path.join(ROOT, d, "*_metadata.json"))
        if m and json.load(io.open(m[0], encoding="utf-8-sig")).get("subject", {}).get("group") != "Patient":
            healthy = d
            break
    fits = {h: {"fixed": None, "coef": None} for h in ("Left", "Right")}
    for h in ("Left", "Right"):
        wins = load_windows(os.path.join(ROOT, healthy), h) if healthy else []
        if not wins:
            continue
        Ls, Ts = [], []
        for w in wins:
            Ls.append(seg_lengths(w["P"])); Ts.append(finger_theta(w["P"]))
        L = np.vstack(Ls); T = np.vstack(Ts)
        fits[h]["fixed"] = np.nanmedian(L, axis=0)
        coef = np.full((len(SEGMENTS), 3), np.nan)
        for j, seg in enumerate(SEGMENTS):
            fg = SEG_FINGER[seg]
            k = ("Thumb", "Index", "Middle", "Ring", "Pinky").index(fg)
            x, y = T[:, k], L[:, j]
            ok = np.isfinite(x) & np.isfinite(y)
            if ok.sum() >= 30:
                A = np.vstack([np.ones(ok.sum()), x[ok], x[ok] ** 2]).T
                coef[j] = np.linalg.lstsq(A, y[ok], rcond=None)[0]
        fits[h]["coef"] = coef

    print("=" * 112)
    print("분절 규칙 실패 유형 주입 검증 — 검출률 (규칙×주입유형×집단), 오검출률 병기")
    print("=" * 112)
    print("B계수 적합에 쓴 자료:", healthy, "(동일 세션에서 평가 → 순환, 오검출 낙관)")

    res = {"provenance": {
        "threshold": THRESH, "min_seg": MIN_SEG, "inject_width_frames": 8,
        "fit_session": healthy, "circularity": "B 계수를 비장애 1세션에서 적합·동평가 → 오검출 낙관",
        "injection_types": ["I1_jump", "I2_loss", "I3_scale", "I4_collapse"],
    }, "detection": {}, "false_alarm": {}, "detail": {}}

    kinds = ["I1_jump", "I2_loss", "I3_scale", "I4_collapse", "NONE"]
    for d in sessions:
        sd = os.path.join(ROOT, d)
        m = glob.glob(os.path.join(sd, "*_metadata.json"))
        grp = (json.load(io.open(m[0], encoding="utf-8-sig")).get("subject", {}) or {}).get("group") if m else None
        gt = "Patient" if grp == "Patient" else "Healthy"
        for hand in ("Left", "Right"):
            wins = load_windows(sd, hand)
            if not wins:
                continue
            for kind in kinds:
                det = []
                for wi, w in enumerate(wins):
                    P = w["P"]
                    if kind == "NONE":
                        Q, sl = P, slice(0, 0)
                    else:
                        idx0 = max(1, int(0.35 * P.shape[0]))
                        Q, sl = inject(P, kind, idx0, 8, rng)
                    L = seg_lengths(Q)
                    T = finger_theta(Q)
                    # 현행
                    v_fixed = violations(L, fits[hand]["fixed"])
                    # B안
                    Lhat = np.full_like(L, np.nan)
                    for j, seg in enumerate(SEGMENTS):
                        k = ("Thumb", "Index", "Middle", "Ring", "Pinky").index(SEG_FINGER[seg])
                        a = fits[hand]["coef"][j]
                        if np.isfinite(a).all():
                            Lhat[:, j] = a[0] + a[1] * T[:, k] + a[2] * T[:, k] ** 2
                    v_b = violations(L, Lhat)
                    if kind == "NONE":
                        det.append((int(np.sum(v_fixed >= MIN_SEG)), int(np.sum(v_b >= MIN_SEG)), P.shape[0]))
                    else:
                        fs, bs = v_fixed[sl], v_b[sl]
                        # 결측으로 분절을 계산할 수 없는 프레임은 '판정보류'로 따로 센다
                        unus = int(np.sum(~np.isfinite(L[sl]).any(axis=1)))
                        det.append((int(np.any(fs >= MIN_SEG)), int(np.any(bs >= MIN_SEG)), unus))
                res["detail"].setdefault(d, {}).setdefault(hand, {})[kind] = det
                if kind == "NONE":
                    nfr = sum(x[2] for x in det)
                    res["false_alarm"]["%s|%s" % (gt, hand)] = {
                        "n_frames": nfr,
                        "fixed_frame_rate": sum(x[0] for x in det) / max(nfr, 1),
                        "B_frame_rate": sum(x[1] for x in det) / max(nfr, 1)}
                else:
                    res["detection"]["%s|%s|%s" % (gt, hand, kind)] = {
                        "n_trials": len(det),
                        "fixed": sum(x[0] for x in det) / len(det),
                        "B": sum(x[1] for x in det) / len(det),
                        "unusable_any": sum(1 for x in det if x[2] > 0) / len(det)}

    print()
    print("■ 주입 검출률 (시행 단위, 0.5초 주입)")
    print("%-34s %6s %9s %9s %9s" % ("집단|손|주입", "시행", "현행", "B안", "판정보류(결측)"))
    for k in sorted(res["detection"]):
        v = res["detection"][k]
        print("%-34s %6d %9.2f %9.2f %9.2f" % (k, v["n_trials"], v["fixed"], v["B"], v["unusable_any"]))
    print()
    print("■ 정상 구간 오검출 (프레임 단위)")
    print("%-22s %9s %12s %10s" % ("집단|손", "프레임", "현행 오검출", "B안 오검출"))
    for k in sorted(res["false_alarm"]):
        v = res["false_alarm"][k]
        print("%-22s %9d %12.4f %10.4f" % (k, v["n_frames"], v["fixed_frame_rate"], v["B_frame_rate"]))

    io.open(OUT, "w", encoding="utf-8").write(json.dumps(res, ensure_ascii=False, indent=2, default=str))
    print()
    print("JSON →", OUT)


if __name__ == "__main__":
    main()

# -*- coding: utf-8 -*-
"""§8.2 분절 규칙 — 실패 유형 4종 주입 검증 v2 (신규 파일).

v1(같은 파일의 이전 저장본)은 기준선을 "집단 중앙값"으로 잡아 29차 `rule_current`(시행 첫 2초)와
비교가 성립하지 않았다. v2는 **29차 정의에 정확히 맞춘다**.

  TOL = 0.20 · MIN_AGREE = 2 · REST_S = 2.0
  θ(손가락) = 그 손가락 14각 정의의 합 (엄지 2개, 나머지 3개)  ← v1은 검지 1개만 써서 달랐다
  현행 : 시행 첫 2초 중앙값 대비 ±20% 벗어난 분절이 2개 이상인 프레임 = 불일치
  B안  : L̂(θ)=a0+a1θ+a2θ² (2차), |L−L̂|/L̂ > 0.20 인 분절 2개 이상 = 불일치
  B 계수는 **LOSO**(나머지 2세션에서 적합 → 남긴 1세션에서 평가)로 순환 제거

주입 유형 (0.5초 ≈ 8프레임, 시행당 1회, 좌우 별도)
    I1 배경 도약 · I2 완전 소실 · I3 스케일 오류 · I4 물체 가림(손끝이 손목으로 붕괴)

측정: ① 시행 단위 검출률 ② **정상 구간 오검출(프레임·시행)** ③ 주입 시야 상실(판정 불가 프레임)
    검출률은 **오검출률과 함께** 읽어야 한다. 오검출이 높으면 "검출"은 규칙이 늘 켜져 있기 때문일 수 있다.

정직: ① B 계수를 환자 세션에서 적합하는 경우가 생긴다(LOSO 한계) → 사양과 다름, 명시.
      ② 환자 세션에 영상 정답이 없어 실제 오류와 정상 운동을 구분하지 못한다.

출력: experiments/results/v15_failure_injection_v2.json
"""
from __future__ import annotations
import csv, glob, io, json, math, os
import numpy as np

ROOT = "capstone/호진파일/outputs/데이터_저장"
OUT = "experiments/results/v15_failure_injection_v2.json"
TOL, MIN_AGREE, REST_S = 0.20, 2, 2.0

FLEX_DEFS = {"Thumb": [(0, 1, 2), (1, 2, 3)],
             "Index": [(0, 5, 6), (5, 6, 7), (6, 7, 8)],
             "Middle": [(0, 9, 10), (9, 10, 11), (10, 11, 12)],
             "Ring": [(0, 13, 14), (13, 14, 15), (14, 15, 16)],
             "Pinky": [(0, 17, 18), (17, 18, 19), (18, 19, 20)]}
SEGMENTS = [(1, 2), (2, 3), (3, 4), (5, 6), (6, 7), (7, 8),
            (9, 10), (10, 11), (11, 12), (13, 14), (14, 15), (15, 16),
            (17, 18), (18, 19), (19, 20)]
FINGER_OF = {s: f for f, defs in () for s in []}
FINGER_OF = {}
for f in ("Thumb",):
    for s in [(1, 2), (2, 3), (3, 4)]:
        FINGER_OF[s] = f
for f, segs in (("Index", [(5, 6), (6, 7), (7, 8)]), ("Middle", [(9, 10), (10, 11), (11, 12)]),
                ("Ring", [(13, 14), (14, 15), (15, 16)]), ("Pinky", [(17, 18), (18, 19), (19, 20)])):
    for s in segs:
        FINGER_OF[s] = f
FNAMES = ("Thumb", "Index", "Middle", "Ring", "Pinky")


def rd(p):
    with io.open(p, encoding="utf-8-sig") as fh:
        return list(csv.DictReader(fh))


def fl(x):
    try:
        v = float(x)
        return v if math.isfinite(v) else None
    except (TypeError, ValueError):
        return None


def interior(a, b, c):
    v1, v2 = a - b, c - b
    n1, n2 = np.linalg.norm(v1), np.linalg.norm(v2)
    if n1 < 1e-9 or n2 < 1e-9:
        return np.nan
    return math.degrees(math.acos(max(-1.0, min(1.0, float(np.dot(v1, v2) / (n1 * n2))))))


def load_windows(sd, hand):
    out = []
    for lf in sorted(glob.glob(os.path.join(sd, "split", "*", "Trial_*", "*_landmarks.csv"))):
        if "pose_landmarks" in lf:
            continue
        df = lf.replace("_landmarks.csv", "_distance_comparison.csv")
        mono = {}
        if os.path.exists(df):
            for r in rd(df):
                if (r.get("Hand") or "") != hand:
                    continue
                fid, t = fl(r.get("Frame_ID")), fl(r.get("capture_monotonic_s"))
                if fid is not None and t is not None:
                    mono[int(fid)] = t
        by = {}
        with io.open(lf, encoding="utf-8-sig") as fh:
            for r in csv.DictReader(fh):
                if (r.get("Hand") or "").strip() != hand:
                    continue
                try:
                    fid = int(float(r["Frame_ID"])); lid = int(float(r["Landmark_ID"]))
                except (KeyError, TypeError, ValueError):
                    continue
                xyz = (fl(r.get("MP_X_m")), fl(r.get("MP_Y_m")), fl(r.get("MP_Z_m")))
                if all(v is not None for v in xyz):
                    by.setdefault(fid, {})[lid] = xyz
        if len(by) < 20:
            continue
        fids = [k for k in sorted(by) if all(0 <= l < 21 for l in by[k])]
        if len(fids) < 20:
            continue
        P = np.full((len(fids), 21, 3), np.nan)
        t = np.full(len(fids), np.nan)
        for i, fid in enumerate(fids):
            for lid, xyz in by[fid].items():
                if 0 <= lid <= 20:
                    P[i, lid] = xyz
            tv = mono.get(fid)
            if tv is not None:
                t[i] = tv
        if not np.isfinite(t).any():
            t = np.arange(len(fids), dtype=float)
        out.append({"trial": os.path.basename(os.path.dirname(lf)), "P": P, "t": t})
    return out


def per_frame(P, t):
    F = P.shape[0]
    L = np.full((F, 15), np.nan)
    for k, (a, b) in enumerate(SEGMENTS):
        L[:, k] = np.linalg.norm(P[:, a] - P[:, b], axis=-1)
    flex = {}
    for f in FNAMES:
        vals = np.full((F, len(FLEX_DEFS[f])), np.nan)
        for m, (i, j, k) in enumerate(FLEX_DEFS[f]):
            for fr in range(F):
                vals[fr, m] = 180.0 - interior(P[fr, i], P[fr, j], P[fr, k])
        flex[f] = np.nansum(vals, axis=1)
    return {"L": L, "flex": flex, "t": t, "F": F}


def rule_current(pf):
    L, t, F = pf["L"], pf["t"], pf["F"]
    viol = np.zeros((15, F), bool)
    for k in range(15):
        d = L[:, k]
        s = (t <= (t[0] + REST_S)) & np.isfinite(d)
        if s.sum() < 8:
            continue
        base = float(np.median(d[s]))
        if base <= 0:
            continue
        viol[k] = np.isfinite(d) & (np.abs(d - base) / base > TOL)
    cnt = viol.sum(axis=0)
    return np.isfinite(L).any(axis=1) & (cnt >= MIN_AGREE)


def rule_B(pf, kappa):
    L, F = pf["L"], pf["F"]
    viol = np.zeros((15, F), bool)
    for k, seg in enumerate(SEGMENTS):
        coef = kappa.get(k)
        if coef is None:
            continue
        th = pf["flex"][FINGER_OF[seg]]
        ok = np.isfinite(L[:, k]) & np.isfinite(th)
        if ok.sum() < 8:
            continue
        Lh = np.polyval(coef, th[ok])
        rel = np.full(ok.sum(), np.inf)
        g = Lh > 1e-6
        rel[g] = np.abs(L[ok, k][g] - Lh[g]) / Lh[g]
        viol[k, np.flatnonzero(ok)] = rel > TOL
    cnt = viol.sum(axis=0)
    return np.isfinite(L).any(axis=1) & (cnt >= MIN_AGREE)


def fit_kappa(pfs):
    kappa = {}
    for k, seg in enumerate(SEGMENTS):
        xs, ys = [], []
        for pf in pfs:
            th = pf["flex"][FINGER_OF[seg]]
            ok = np.isfinite(pf["L"][:, k]) & np.isfinite(th)
            xs.append(th[ok]); ys.append(pf["L"][ok, k])
        x = np.concatenate(xs) if xs else np.array([])
        y = np.concatenate(ys) if ys else np.array([])
        if x.size >= 50:
            kappa[k] = np.polyfit(x, y, 2)
    return kappa


def inject(P, kind, idx0, width, rng):
    Q = P.copy()
    sl = slice(idx0, min(idx0 + width, P.shape[0]))
    if kind == "I1_jump":
        d = rng.normal(size=3); d = d / np.linalg.norm(d) * 0.150
        Q[sl, 8] = Q[sl, 8] + d
    elif kind == "I2_loss":
        Q[sl, 8] = np.nan
    elif kind == "I3_scale":
        w = P[sl, 0:1, :]; Q[sl] = w + 1.5 * (P[sl] - w)
    elif kind == "I4_collapse":
        Q[sl, 8] = P[sl, 0]
    return Q, sl


def main():
    sessions = [d for d in sorted(os.listdir(ROOT)) if os.path.isdir(os.path.join(ROOT, d))]
    groups = {}
    for d in sessions:
        m = glob.glob(os.path.join(ROOT, d, "*_metadata.json"))
        groups[d] = ("Patient" if m and
                     json.load(io.open(m[0], encoding="utf-8-sig")).get("subject", {}).get("group") == "Patient"
                     else "Healthy")
    rng = np.random.default_rng(20261002)

    # 세션×손 → per_frame 사전계산
    PF = {}
    for d in sessions:
        for hand in ("Left", "Right"):
            wins = load_windows(os.path.join(ROOT, d), hand)
            if wins:
                PF[(d, hand)] = [per_frame(w["P"], w["t"]) for w in wins]
                PF[(d, hand) + ("raw",)] = [w["P"] for w in wins]

    res = {"provenance": {"tol": TOL, "min_agree": MIN_AGREE, "rest_s": REST_S,
                          "theta": "손가락 14각 합(엄지2·나머지3)", "fit": "LOSO(나머지 2세션)",
                          "fit_caveat": "비장애 세션을 남길 때 환자 세션에서 B를 적합 → 사양과 다름",
                          "time_axis": "capture_monotonic_s (29차는 time_s 사용)"},
           "detection": {}, "false_alarm": {}}

    for d in sessions:
        for hand in ("Left", "Right"):
            if (d, hand) not in PF:
                continue
            others = [pf for (dd, hh) in PF if dd != d and hh in ("Left", "Right") and (dd, hh) != (d, hand)
                      for pf in PF[(dd, hh)]]
            kappa = fit_kappa(others)
            wins, raws = PF[(d, hand)], PF[(d, hand) + ("raw",)]
            gt = groups[d]
            # 정상 오검출
            fa_f = fa_t = fa_fB = fa_tB = 0
            nfr = 0
            for pf in wins:
                f = rule_current(pf); b = rule_B(pf, kappa)
                nfr += pf["F"]
                fa_f += int(f.sum()); fa_t += int(f.any())
                fa_fB += int(b.sum()); fa_tB += int(b.any())
            res["false_alarm"]["%s|%s" % (gt, hand)] = {
                "n_trials": len(wins), "n_frames": nfr,
                "cur_frame": fa_f / max(nfr, 1), "cur_trial": fa_t / len(wins),
                "B_frame": fa_fB / max(nfr, 1), "B_trial": fa_tB / len(wins)}
            # 주입
            for kind in ("I1_jump", "I2_loss", "I3_scale", "I4_collapse"):
                dc = db = 0
                for wi, pf in enumerate(wins):
                    P = raws[wi]
                    idx0 = max(1, int(0.35 * P.shape[0]))
                    Q, sl = inject(P, kind, idx0, 8, rng)
                    pf2 = per_frame(Q, pf["t"])
                    dc += int(rule_current(pf2)[sl].any())
                    db += int(rule_B(pf2, kappa)[sl].any())
                res["detection"]["%s|%s|%s" % (gt, hand, kind)] = {
                    "n_trials": len(wins), "cur": dc / len(wins), "B": db / len(wins)}

    print("=" * 116)
    print("분절 규칙 실패유형 주입 v2 — 29차 정의 정합 (첫 2초 기준선 / θ=손가락 굴곡합 / B는 LOSO)")
    print("=" * 116)
    print("■ 주입 검출률 (시행 단위)")
    print("%-32s %5s %9s %9s" % ("집단|손|주입", "시행", "현행", "B안"))
    for k in sorted(res["detection"]):
        v = res["detection"][k]
        print("%-32s %5d %9.2f %9.2f" % (k, v["n_trials"], v["cur"], v["B"]))
    print()
    print("■ 정상 구간 오검출 — 검출률은 이 값과 함께 읽어야 한다")
    print("%-20s %6s %6s %11s %11s %10s %10s" % ("집단|손", "시행", "프레임", "현행(프레임)", "현행(시행)", "B(프레임)", "B(시행)"))
    for k in sorted(res["false_alarm"]):
        v = res["false_alarm"][k]
        print("%-20s %6d %6d %11.3f %11.3f %10.3f %10.3f" % (
            k, v["n_trials"], v["n_frames"], v["cur_frame"], v["cur_trial"], v["B_frame"], v["B_trial"]))
    io.open(OUT, "w", encoding="utf-8").write(json.dumps(res, ensure_ascii=False, indent=2, default=str))
    print()
    print("JSON →", OUT)


if __name__ == "__main__":
    main()

